questionvariables.text:
/* scenario 0: NOT a function (one x-value paired with two different y-values)
   scenario 1: a function, many-to-one (one y-value shared by two x-values)
   scenario 2: a function, one-to-one (all x-values and all y-values distinct) */
scenario: rand(3);
p1: rand_with_prohib(1, 9, []);
p2: rand_with_prohib(1, 9, [p1]);
p3: rand_with_prohib(1, 9, [p1, p2]);
q1: rand_with_prohib(1, 9, []);
q2: rand_with_prohib(1, 9, [q1]);
q3: rand_with_prohib(1, 9, [q1, q2]);
xa: p1; ya: q1;
xb: if scenario=0 then p1 else p2;
yb: if scenario=1 then q1 else q2;
xc: if scenario=0 then p2 else p3;
yc: if scenario=1 then q2 else q3;
/* Shuffle the pairs so the repeated value is not always in the first two pairs. */
pairs: random_permutation([[xa, ya], [xb, yb], [xc, yc]]);
ta1: [[isfn, is(scenario>0), "Yes, it is a function"], [notfn, is(scenario=0), "No, it is not a function"]];
ta2: [[onetoone, is(scenario=2), "One-to-one"], [manytoone, is(scenario=1), "Many-to-one"], [notapp, is(scenario=0), "Not applicable (not a function)"]];
tac1: first(mcq_correct(ta1));
tac2: first(mcq_correct(ta2));
